<script lang="ts">
import type{HudProfile}from './launcher_plugins';
let{profile=$bindable(),onchange=()=>{}}:{profile:HudProfile;onchange?:()=>void}=$props();
const themes=[['End','#A855F7'],['Cian','#06B6D4'],['PvP','#EF4444'],['Esmeralda','#10B981'],['Dorado','#F59E0B'],['Blanco','#FFFFFF'],['Oscuro','#353541']];
</script>
<section class="appearance"><h3>Ajustes y colores del HUD</h3><p>El diseño se guarda en tu perfil y se aplica en vivo.</p><div class="themes">{#each themes as [label,color]}<button style:--swatch={color} class:active={profile.accent===color} onclick={()=>{profile.accent=color;onchange();}}><i></i>{label}</button>{/each}</div>
<div class="colors">{#each [['accent','Bordes y acento'],['text_color','Texto'],['background_color','Fondo']] as [key,label]}<label>{label}<input type="color" value={profile[key as 'accent'|'text_color'|'background_color']} oninput={(e)=>{profile[key as 'accent'|'text_color'|'background_color']=e.currentTarget.value;onchange();}}/></label>{/each}</div>
<label>Transparencia del menú <output>{Math.round(profile.menu_transparency*100)}%</output><input type="range" min=".1" max=".95" step=".01" bind:value={profile.menu_transparency} oninput={onchange}/></label>
<label class="check"><input type="checkbox" bind:checked={profile.menu_blur} onchange={onchange}/>Desenfoque del fondo</label><label class="check"><input type="checkbox" bind:checked={profile.chroma} onchange={onchange}/>Chroma RGB</label>
<label class="check"><input type="checkbox" bind:checked={profile.title_theme} onchange={onchange}/>Menú principal con tema TP (conector compatible)</label><hr/><h3>Días del mundo</h3><label class="check"><input type="checkbox" bind:checked={profile.days_with_fps} onchange={onchange}/>Mostrar el día junto a los FPS</label><label>Ajuste de sincronización (días)<input type="number" min="-1000000" max="1000000" step="1" bind:value={profile.day_offset} onchange={onchange}/></label><small>Se suma al día que envía el mundo. Usa 0 para volver a la lectura automática.</small>
<button onclick={()=>{profile.menu_offset_x=profile.menu_offset_y=0;for(const item of profile.modules){item.x=null;item.y=null;}onchange();}}>Centrar menú y restablecer posiciones</button></section>
<style>.appearance{display:grid;gap:20px;color:inherit}.appearance h3{margin:0;font-size:15px}.appearance p,.appearance small{font-size:11px;color:#b9adc5;line-height:1.6}.themes,.colors{display:flex;gap:8px;flex-wrap:wrap}.themes button{display:flex;align-items:center;gap:7px}.themes i{background:var(--swatch);width:12px;height:12px}.appearance button{background:#ffffff08;color:inherit;border:1px solid #ffffff22;padding:9px;cursor:pointer}.appearance .active{border-color:var(--swatch)}label{display:grid;gap:8px;font-size:12px}input[type=range]{width:100%;accent-color:var(--hud-accent,#a855f7)}input[type=color]{width:90px;height:33px;padding:0;border:0;background:none}input[type=number]{background:#0b0b0f;color:inherit;border:1px solid #ffffff20;padding:8px}.check{display:flex;gap:9px;align-items:center}hr{width:100%;border:0;border-top:1px solid #ffffff18}</style>
